// Importing necessary modules and components
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import Modal from 'react-modal'; // Import the Modal component from the react-modal library
import YouTube from 'react-youtube';
import Loader from 'react-loader-spinner'
import '../CSS/movieslist.css';
const apiKey = '499d99db6ce23991d21afde0deede0f1';
const baseUrl = 'https://api.themoviedb.org/3';
function MoviesList({ category, addToWatchlist }) {
  // Setting up state for the list of movies, selected movie, and trailer video
  const [movies, setMovies] = useState([]);
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [trailerVideo, setTrailerVideo] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const playTrailer = async (movie) => {
    setIsLoading(true);
    setSelectedMovie(movie);
    const response = await axios.get(
      `${baseUrl}/movie/${movie.id}/videos`,
      {
        params: {
          api_key: apiKey,
        },
      }
    );
    const trailer = response.data.results.find(
      (video) => video.type === 'Trailer' && video.site === 'YouTube'
    );
    setTrailerVideo(trailer);
    setIsLoading(false);
  };
  const closeTrailer = () => {
    setSelectedMovie(null);
    setTrailerVideo(null);
  };
  useEffect(() => {
    const fetchData = async () => {
      let endpoint;
      switch (category) {
        case 'hollywood':
          endpoint = '/movie/popular';
          break;
        case 'bollywood':
          endpoint = '/discover/movie?with_original_language=hi';
          break;
        case 'lollywood':
          endpoint = '/discover/movie?with_original_language=ur';
          break;
        default:
          return;
      }
      const response = await axios.get(`${baseUrl}${endpoint}`, {
        params: {
          api_key: apiKey,
        },
      });
      setMovies(response.data.results);
    };
    fetchData();
  }, [category]);
  const handleScrollClick = (direction) => {
    const container = document.querySelector(`.movies-container-${category}`);
    if (direction === 'left') {
      container.scrollBy({ left: -300, behavior: 'smooth' });
    } else if (direction === 'right') {
      container.scrollBy({ left: 300, behavior: 'smooth' });
    }
  };
  return (
    <div>
      <h2>{category}</h2>
      <div className="movies-list">
        <button className="scroll-button" onClick={() => handleScrollClick('left')}>
          {'<'}
        </button>
        <div className={`movies-container movies-container-${category}`}>
          {movies.map((movie) => (
            <div key={movie.id} className="movie-card">
              <Link to={`/movie/${movie.id}`}>
                <img
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`}
                  alt={movie.title}
                  style={{ height: '300px' }}
                />
                <h3 style={{ height: '40px', zIndex: 1 }}>{movie.title}</h3>
              </Link>
              <div style={{ display: 'flex', flexDirection: 'column' }}>
                <button onClick={() => addToWatchlist(movie)}>
                  Watchlist <span>+</span>
                </button>
                <button onClick={() => playTrailer(movie)}>
                  <span>▶</span> Play
                </button>
              </div>
            </div>
          ))}
        </div>
        <button className="scroll-button" onClick={() => handleScrollClick('right')}>
          {'>'}
        </button>
      </div>
      {trailerVideo && (
        <>
          <Modal
            isOpen={true}
            onRequestClose={closeTrailer}
            style={{
              overlay: {
                backgroundColor: 'rgba(0, 0, 0, 0.75)',
              },
              content: {
                top: '50%',
                left: '50%',
                right: 'auto',
                bottom: 'auto',
                marginRight: '-50%',
                transform: 'translate(-50%, -50%)',
                width: '80%',
                height: '80%',
                padding: 0,
                overflow : 'hidden',
              },
            }}
          >
            <div
              className={`modal-content ${trailerVideo ? 'open' : ''}`}
              style={{ position: 'relative', width: '100%', height: '100%' }} // Add styles to make the div fill its parent container
            >
              {isLoading && (
                <div>
                  <div className="loader">
                  <Loader
                    type="TailSpin"
                    color="#00BFFF"
                    height={80}
  width={80}
/>

                  </div>
                </div>
              )}
              <YouTube
                videoId={trailerVideo.key}
                opts={{
                  height: '100%',
                  width: '100%',
                  playerVars: {
                    autoplay: 1,
                    },
                }}
              />

            </div>
          </Modal>         
          <button
            onClick={closeTrailer}
            onMouseEnter={(e) => (e.target.style.backgroundColor = '#000')}
            onMouseLeave={(e) => (e.target.style.backgroundColor = 'grey')}
            style={{
              position: 'fixed',
              top: 10,
              right: 10,
              fontSize: '24px',
              backgroundColor: 'grey',
              border: 'none',
              color: '#fff',
            }}
          >
            ×
          </button>
        </>
      )}
    </div>
  );
}
export default MoviesList;
